-- Gamma — Презентації
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gamma.app' OR LOWER(`name`) = LOWER('Gamma'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gamma', NULL, 'https://gamma.app', NULL, NULL, 'AI-конструктор презентацій, документів, сайтів і дописів для соцмереж: з одного запиту створює готові слайди з дизайном, текстом і зображеннями.', 'An AI builder for presentations, documents, websites and social posts: from a single prompt it creates ready slides with design, text and images.', 'Gamma перетворює ідею чи текст на готову презентацію, документ, простий сайт або допис для соцмереж. Досить описати тему чи вставити нотатки — AI складе структуру, напише текст, підбере макети й зображення, а далі все можна доопрацювати вручну чи командами AI. Є імпорт з PDF і PPTX та експорт у PDF, PPTX, PNG і Google Slides, публікація на власних доменах, аналітика переглядів, а в старших тарифах — API. Тарифи за місце на місяць при річній оплаті: Free — 400 кредитів при реєстрації; Plus — $9 (1 000 кредитів, без брендингу Gamma); Pro — $18 (4 000 кредитів, преміальні моделі зображень, власний брендинг, API); Ultra — $90 (20 000 кредитів, найпотужніші моделі для тексту, зображень і відео).', 'Gamma turns an idea or text into a ready presentation, document, simple website or social post. Just describe the topic or paste your notes — AI builds the structure, writes the text, picks layouts and images, and you can then refine everything by hand or with AI commands. It imports PDF and PPTX and exports to PDF, PPTX, PNG and Google Slides, publishes to custom domains, offers view analytics and, on higher plans, an API. Plans per seat a month billed annually: Free — 400 credits at signup; Plus — $9 (1,000 credits, no Gamma branding); Pro — $18 (4,000 credits, premium image models, custom branding, API); Ultra — $90 (20,000 credits, the most advanced text, image and video models).', 'Презентація, документ чи сайт з одного запиту
Імпорт PDF і PPTX
Експорт у PDF, PPTX, PNG і Google Slides
Власні домени й аналітика переглядів
API (Pro)', 'A deck, doc or site from one prompt
Import from PDF and PPTX
Export to PDF, PPTX, PNG and Google Slides
Custom domains and view analytics
API (Pro)', 'Студенти, викладачі, маркетологи, консультанти й усі, кому часто треба робити презентації.', 'Students, teachers, marketers, consultants and anyone who often needs to make presentations.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
