INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Beautiful.ai', NULL, 'https://www.beautiful.ai', NULL, NULL, 'Сервіс презентацій з AI і «розумними» слайдами, які самі вирівнюють дизайн, коли ви додаєте контент; імпорт і експорт PowerPoint, брендинг для команд.', 'A presentation tool with AI and ''smart'' slides that keep the design aligned as you add content; PowerPoint import and export and team branding.', 'Beautiful.ai допомагає робити охайні презентації без ручного вирівнювання. Понад 300 макетів Smart Slides автоматично підлаштовують розташування елементів, коли ви додаєте чи прибираєте текст, зображення й діаграми, а AI генерує вміст і цілі слайди за запитом без обмежень. Підтримуються імпорт і експорт PowerPoint та власні шаблони з фірмовим стилем; командні тарифи додають спільне редагування, аналітику, SSO та відповідність GDPR. Тарифи: Pro — $14,50 на місяць при річній оплаті; Team — $40 за користувача на місяць при річній оплаті ($50 помісячно); Enterprise — за запитом. Для всіх тарифів є 14-денний пробний період.', 'Beautiful.ai helps you make clean presentations without manual alignment. More than 300 Smart Slide layouts automatically adjust the arrangement of elements as you add or remove text, images and charts, and AI generates content and whole slides on request without limits. PowerPoint import and export and custom branded templates are supported; team plans add collaborative editing, analytics, SSO and GDPR compliance. Plans: Pro — $14.50 a month billed annually; Team — $40 per user a month billed annually ($50 monthly); Enterprise on request. All plans have a 14-day free trial.', '300+ «розумних» макетів Smart Slides
Необмежена AI-генерація вмісту
Імпорт і експорт PowerPoint
Фірмові шаблони й командна робота', '300+ Smart Slide layouts
Unlimited AI content generation
PowerPoint import and export
