INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pitch', NULL, 'https://pitch.com', NULL, NULL, 'Сервіс для командних презентацій з AI-генератором слайдів, спільним редагуванням у реальному часі, шаблонами й аналітикою переглядів.', 'A collaborative presentation tool with an AI slide generator, real-time co-editing, templates and view analytics.', 'Pitch створено для команд, які роблять презентації разом. AI-генератор швидко складає перші слайди за запитом, а далі колеги можуть одночасно редагувати, коментувати й призначати слайди, користуватися спільними шаблонами та фірмовим стилем. Презентацію можна показувати чи надсилати посиланням і бачити аналітику переглядів. Усі тарифи дають необмежену кількість презентацій. Ціни в євро: Free — 100 разових AI-кредитів; Plus — €10 на місяць (500 AI-кредитів); Team — €15 на місяць (до 25 учасників); Business — €20 на місяць (750 кредитів, до 200 учасників); при річній оплаті знижка 17%; Enterprise — за запитом.', 'Pitch is built for teams that create presentations together. The AI generator quickly drafts the first slides from a prompt, and then colleagues can edit at the same time, comment and assign slides, and use shared templates and brand styles. A presentation can be presented or shared by link, with view analytics. All plans include unlimited presentations. Prices in euros: Free — 100 one-time AI credits; Plus — €10 a month (500 AI credits); Team — €15 a month (up to 25 members); Business — €20 a month (750 credits, up to 200 members); 17% off with annual billing; Enterprise on request.', 'AI-генератор слайдів
Спільне редагування в реальному часі
Спільні шаблони й фірмовий стиль
Аналітика переглядів', 'AI slide generator
Real-time co-editing
Shared templates and brand styles
View analytics', 'Стартапи, маркетингові й продажні команди, які спільно готують презентації.', 'Startups, marketing and sales teams that prepare presentations together.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
