-- Equals — Таблиці
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'equals.com' OR LOWER(`name`) = LOWER('Equals'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Equals', NULL, 'https://equals.com', NULL, NULL, 'Таблиця, підключена напряму до даних компанії: BI, дашборди, автоматична звітність і AI-аналітика для команд без окремого аналітика.', 'A spreadsheet connected directly to company data: BI, dashboards, automated reporting and AI analytics for teams.', 'Equals поєднує звичну таблицю з бізнес-аналітикою. Дані з бази, сховища та бізнес-сервісів підтягуються в таблицю автоматично й оновлюються за розкладом, на їх основі будуються дашборди й регулярні звіти, які можна надсилати в Slack, а AI допомагає ставити запитання до даних і знаходити інсайти. Усі тарифи включають необмежену кількість переглядачів і редакторів та виділеного аналітика для впровадження. Серед клієнтів — Notion, Descript та Intercom. Тарифи на рік: Essential — $24 000 (3 конектори, синхронізація раз на 6 годин); Business — $36 000 (5 конекторів або сховище, щогодинна синхронізація); Enterprise — $60 000 (необмежені конектори, синхронізація кожні 15 хвилин, SSO).', 'Equals combines a familiar spreadsheet with business intelligence. Data from your database, warehouse and business tools flows into the sheet automatically and refreshes on a schedule; on top of it you build dashboards and recurring reports that can be sent to Slack, and AI helps you ask questions of the data and find insights. All plans include unlimited viewers and editors and a dedicated analyst for implementation. Customers include Notion, Descript and Intercom. Annual plans: Essential — $24,000 (3 connectors, 6-hour sync); Business — $36,000 (5 connectors or a warehouse, hourly sync); Enterprise — $60,000 (unlimited connectors, 15-minute sync, SSO).', 'Таблиця з прямим підключенням до даних
Дашборди й автоматична звітність
AI-аналітика
Інтеграція зі Slack', 'Spreadsheet connected directly to data
Dashboards and automated reporting
AI analytics
Slack integration', 'Фінансові, продуктові й операційні команди компаній, що ростуть.', 'Finance, product and operations teams at growing companies.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
